SELECT ?subjectLabel ?objectLabel ?subjectType WHERE {
  ?subject wdt:P9002 ?object .
  OPTIONAL { ?subject wdt:P31 ?subjectType . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?subject ?object
LIMIT 10 OFFSET 0

